//! The org-root golden fixture, read from Rust.
//!
//! `rine-core/test/fixtures/org-root-v1.json` is generated by the TypeScript
//! stack from `@noble/post-quantum` and `@scure/bip39`. These tests are the
//! cross-implementation check: the same seeds must expand to the same ML-KEM-768
//! and ML-DSA-65 keys here, and the escrow plaintext the generator wrote must
//! parse with the Rust reader. A public mirror of `rine-mls` has no `rine-core`
//! beside it, so when `rine-core/` is absent the tests skip; a deleted fixture
//! file inside a present directory is a failure, not a skip.

mod common;

use common::fixture;
use rine_mls_core::{mldsa, mlkem, EpochReader, EscrowFault, RineMlsError};
use serde_json::Value;

/// The parsed fixture, or `None` in a public mirror of `rine-mls`.
fn load_fixture() -> Option<Value> {
    fixture::load_json("rine-core/test/fixtures/org-root-v1.json")
}

/// The JSON field names one seeded key family lives under.
struct KeyKind {
    seed: &'static str,
    /// The org's key, when the family has one (only ML-DSA-65 does).
    org: Option<&'static str>,
    branch: &'static str,
    gen: &'static str,
    acvp: &'static str,
    acvp_seed: &'static str,
    acvp_pk: &'static str,
}

const ML_KEM_768: KeyKind = KeyKind {
    seed: "seed",
    org: None,
    branch: "escrow_ml_kem_768",
    gen: "ml_kem_768",
    acvp: "ml_kem_768",
    acvp_seed: "seed",
    acvp_pk: "ek",
};
const ML_DSA_65: KeyKind = KeyKind {
    seed: "xi",
    org: Some("ml_dsa_65"),
    branch: "ml_dsa_65",
    gen: "ml_dsa_65",
    acvp: "ml_dsa_65",
    acvp_seed: "seed",
    acvp_pk: "pk",
};

fn hex_field(value: &Value, field: &str) -> Vec<u8> {
    hex::decode(value[field].as_str().expect("hex field")).expect("hex field")
}

fn be32(bytes: &[u8]) -> u32 {
    u32::from_be_bytes(bytes.try_into().expect("4 bytes"))
}

/// Every `(seed, expected_public_key)` pair the fixture holds for one family:
/// the org key, each branch, each agent generation, and the ACVP cases.
fn key_pairs(fixture: &Value, kind: &KeyKind) -> Vec<(Vec<u8>, Vec<u8>)> {
    let mut pairs = Vec::new();
    let mut push = |entry: &Value, seed: &str, pk: &str| {
        pairs.push((hex_field(entry, seed), hex_field(entry, pk)));
    };

    for root in fixture["roots"]["roots"].as_array().expect("roots") {
        if let Some(org) = kind.org.and_then(|field| root["org"].get(field)) {
            push(org, kind.seed, "pk");
        }
        for branch in root["branches"].as_object().expect("branches").values() {
            push(&branch[kind.branch], kind.seed, "pk");
        }
        for agent in root["agents"].as_array().expect("agents") {
            for gen in agent["gens"].as_array().expect("gens") {
                push(&gen[kind.gen], kind.seed, "pk");
            }
        }
    }
    for case in fixture["acvp"][kind.acvp]["cases"]
        .as_array()
        .expect("cases")
    {
        push(case, kind.acvp_seed, kind.acvp_pk);
    }
    pairs
}

/// Walk one family and check every pair against `derive`.
fn check_keys(fixture: &Value, kind: &KeyKind, derive: impl Fn(&[u8]) -> Vec<u8>) {
    let pairs = key_pairs(fixture, kind);
    assert!(!pairs.is_empty(), "the fixture walk found no keys");

    for (seed, expected) in pairs {
        assert_eq!(derive(&seed), expected, "seed {}", hex::encode(&seed));
    }
}

/// The 16 raw bytes MLS uses as a group id: the slot's UUID without hyphens.
fn slot_group_id(slot: &Value) -> Vec<u8> {
    hex::decode(
        slot["group_id"]
            .as_str()
            .expect("group_id")
            .replace('-', ""),
    )
    .expect("group id hex")
}

#[test]
fn test_ml_kem_768_fixture_when_seeded_matches_the_public_keys() {
    let Some(fixture) = load_fixture() else {
        return;
    };
    check_keys(&fixture, &ML_KEM_768, |seed| {
        mlkem::key_pair_from_seed(seed).expect("keygen").1.to_vec()
    });
}

#[test]
fn test_ml_dsa_65_fixture_when_seeded_matches_the_public_keys() {
    let Some(fixture) = load_fixture() else {
        return;
    };
    check_keys(&fixture, &ML_DSA_65, |seed| {
        mldsa::public_key_from_seed(seed).expect("keygen").to_vec()
    });
}

#[test]
fn test_epoch_reader_when_built_from_the_fixture_escrow_reads_it_and_refuses_another_epoch() {
    let Some(fixture) = load_fixture() else {
        return;
    };
    let escrow = &fixture["mls_escrow"];
    let group_id = slot_group_id(&escrow["slot"]);
    let epoch = escrow["slot"]["epoch"].as_u64().expect("epoch");
    let bytes = hex_field(&escrow["plaintext"], "bytes");

    EpochReader::from_escrow(&group_id, epoch, &bytes).expect("the fixture escrow parses");

    let err = EpochReader::from_escrow(&group_id, epoch + 1, &bytes)
        .err()
        .expect("wrong epoch");
    assert!(
        matches!(err, RineMlsError::InvalidEscrow(EscrowFault::SlotMismatch)),
        "got {err:?}"
    );
}

#[test]
fn test_fingerprint_when_given_the_fixture_epoch_authenticator_matches_the_slot() {
    let Some(fixture) = load_fixture() else {
        return;
    };
    let slot = &fixture["mls_escrow"]["slot"];
    let fp = rine_mls_core::fingerprint(&hex_field(slot, "epoch_authenticator")).expect("fp");

    assert_eq!(fp.as_slice(), hex_field(slot, "fp"));
}

#[test]
fn test_escrow_plaintext_when_hand_decoded_matches_the_fixture_fields() {
    let Some(fixture) = load_fixture() else {
        return;
    };
    let plaintext = &fixture["mls_escrow"]["plaintext"];
    let bytes = hex_field(plaintext, "bytes");

    assert_eq!(bytes[0], 1, "version");
    assert_eq!(u16::from_be_bytes([bytes[1], bytes[2]]), 0xF057, "suite");
    assert_eq!(
        be32(&bytes[3..7]),
        plaintext["leaf_count"].as_u64().expect("leaf_count") as u32
    );
    assert_eq!(hex::encode(&bytes[7..39]), plaintext["sender_data_secret"]);
    assert_eq!(hex::encode(&bytes[39..71]), plaintext["encryption_secret"]);

    let context_len = be32(&bytes[71..75]) as usize;
    assert_eq!(
        hex::encode(&bytes[75..75 + context_len]),
        plaintext["group_context"]
    );

    let n = be32(&bytes[75 + context_len..79 + context_len]) as usize;
    let leaves = plaintext["leaves"].as_array().expect("leaves");
    assert_eq!(n, leaves.len());

    for (i, leaf) in leaves.iter().enumerate() {
        let off = 79 + context_len + 36 * i;
        assert_eq!(
            be32(&bytes[off..off + 4]),
            leaf["leaf_index"].as_u64().expect("leaf_index") as u32
        );
        assert_eq!(hex::encode(&bytes[off + 4..off + 36]), leaf["pk"]);
    }

    assert_eq!(bytes.len(), 71 + 8 + context_len + 36 * n);
    assert_eq!(
        bytes.len(),
        plaintext["length"].as_u64().expect("length") as usize
    );
}

#[test]
fn test_epoch_reader_when_given_a_bad_fixture_plaintext_refuses_it() {
    let Some(fixture) = load_fixture() else {
        return;
    };
    let escrow = &fixture["mls_escrow"];
    let group_id = slot_group_id(&escrow["slot"]);
    let epoch = escrow["slot"]["epoch"].as_u64().expect("epoch");

    for case in escrow["negatives"]["bad_plaintexts"]
        .as_array()
        .expect("bad_plaintexts")
    {
        let name = case["name"].as_str().expect("name");
        let err = EpochReader::from_escrow(&group_id, epoch, &hex_field(case, "plaintext"))
            .err()
            .expect(name);

        match name {
            "wrong_version" => assert!(
                matches!(
                    err,
                    RineMlsError::InvalidEscrow(EscrowFault::UnsupportedVersion(2))
                ),
                "{name}: got {err:?}"
            ),
            "wrong_suite" => assert!(
                matches!(err, RineMlsError::UnsupportedCipherSuite { .. }),
                "{name}: got {err:?}"
            ),
            other => panic!("unhandled negative case {other}"),
        }
    }
}
